/// Matches `g_IsIntegerFormat` in `third_party/nrd/Source/InstanceImpl.cpp`.
const fn is_integer_format(format: u32) -> bool {
    matches!(format, 2 | 6 | 10 | 15 | 20 | 25 | 28 | 31 | 34 | 37 | 41)
}

